const crypto = require('crypto');
const input = $input.first().json; const headers = input.headers || {}; const body = input.body || {};
function canonical(v) { if (Array.isArray(v)) return '[' + v.map(canonical).join(',') + ']'; if (v && typeof v === 'object') return '{' + Object.keys(v).sort().map(k => JSON.stringify(k) + ':' + canonical(v[k])).join(',') + '}'; return JSON.stringify(v); }
const ts=String(headers['x-lendloop-timestamp']||headers['X-Lendloop-Timestamp']||''); const nonce=String(headers['x-lendloop-nonce']||headers['X-Lendloop-Nonce']||''); const supplied=String(headers['x-lendloop-signature']||headers['X-Lendloop-Signature']||'');
if (!/^\d+$/.test(ts)||Math.abs(Date.now()/1000-Number(ts))>300||!/^[a-zA-Z0-9-]{16,100}$/.test(nonce)) throw new Error('Invalid timestamp or nonce');
const signed='POST\n/webhook/lendloop-events\n'+ts+'\n'+nonce+'\n'+canonical(body); const expected=crypto.createHmac('sha256',$env.INTEGRATION_HMAC_SECRET).update(signed).digest('hex'); const a=Buffer.from(supplied,'hex'),b=Buffer.from(expected,'hex'); if(a.length!==b.length||!crypto.timingSafeEqual(a,b)) throw new Error('Invalid HMAC');
if(!body.eventKey||!body.eventType||!body.recipientRef||!body.loan?.id||!body.status) throw new Error('Required event fields missing');
const payload={eventKey:body.eventKey,eventType:body.eventType,loanId:body.loan.id,status:body.status,recipientRef:body.recipientRef}; const timestamp=String(Math.floor(Date.now()/1000)); const requestNonce=crypto.randomUUID(); const path='/lendloop/automation/event'; const canonicalBody=canonical(payload); const message='POST\n'+path+'\n'+timestamp+'\n'+requestNonce+'\n'+canonicalBody; const signature=crypto.createHmac('sha256',$env.INTEGRATION_HMAC_SECRET).update(message).digest('hex');
return [{json:{url:$env.CONVEX_HTTP_URL+path,payload,headers:{'content-type':'application/json','x-lendloop-timestamp':timestamp,'x-lendloop-nonce':requestNonce,'x-lendloop-signature':signature},mock:{eventKey:body.eventKey,kind:body.eventType,recipientRef:body.recipientRef,item:body.loan.item,status:body.status,delivery:'logged-mock'}}}];
